head.script:


    scwin.getType = function ( info ) {

        var rowIdx = info.rowIndex;
        var colIdx = info.colIndex;
        var status = grd_result_file.getRowStatus(rowIdx);
        var strId = "random_" + status + "_" + rowIdx + "_" + colIdx;
        var result = {};

        switch (status) {
            case "C":
                result.id = strId;
                result.inputType = "textImage";
                result.options = {viewType: "icon", imageSrc: "grd_custom_txtImg_imgClickFunc_WAEA-237_(WSQ-5982).svg", imageWidth:"26", imageHeight: "26", imageClickFunction: "scwin.ff_CustSearchPop("+info.rowIndex+")"};
                grd_result_file.setCellClass(rowIdx, colIdx, "req");
                grd_result_file.setReadOnly("cell", rowIdx, colIdx, true);
                break;
            default:
                //debugger;    
                result.id = strId;
                result.inputType = "textImage";
                result.options = {};
                //grd_result.setCellClass(rowIdx, colIdx, "req");
                grd_result_file.setReadOnly("cell", rowIdx, colIdx, true);
                break;
        }

        return result;

	};

